CREATE INDEX "send_log_message_id_idx" ON "notifications"."send_log" USING btree ("message_id");--> statement-breakpoint
CREATE INDEX "send_log_subject_idx" ON "notifications"."send_log" USING btree ("subject_type","subject_id","submitted_at");--> statement-breakpoint
