-- Part two: hand-written CHECK constraints. They hold the text columns to the values in
-- packages/types/src/send-log.ts, which drizzle-kit does not generate.
ALTER TABLE "notifications"."send_log"
	ADD CONSTRAINT "send_log_subject_type_check" CHECK ("subject_type" IN ('order', 'quote'));
