-- kind marks the lead-time request to Production, the one alert looked up by kind.
ALTER TABLE "notifications"."send_log"
	ADD CONSTRAINT "send_log_kind_check" CHECK ("kind" IS NULL OR "kind" = 'lead-time-request');
