ALTER TABLE "notifications"."send_log"
	ADD CONSTRAINT "send_log_message_id_check" CHECK (length(btrim("message_id")) > 0);
--> statement-breakpoint
ALTER TABLE "notifications"."send_log"
	ADD CONSTRAINT "send_log_actor_check" CHECK (length(btrim("actor")) > 0);
--> statement-breakpoint
ALTER TABLE "notifications"."send_log"
	ADD CONSTRAINT "send_log_subject_label_check" CHECK ("subject_label" IS NULL OR length(btrim("subject_label")) > 0);
