-- Every failure column is set only on a failed row.
ALTER TABLE "notifications"."send_log"
	ADD CONSTRAINT "send_log_failure_reason_outcome_check" CHECK ("failure_reason" IS NULL OR "outcome" = 'failed');
--> statement-breakpoint
ALTER TABLE "notifications"."send_log"
	ADD CONSTRAINT "send_log_failure_detail_outcome_check" CHECK ("failure_detail" IS NULL OR "outcome" = 'failed');
