-- A failure is either nobody to send to (failure_reason) or a relay failure (failure_detail,
-- failure_permanent), never both.
ALTER TABLE "notifications"."send_log"
	ADD CONSTRAINT "send_log_failure_kinds_exclusive_check" CHECK ("failure_reason" IS NULL OR ("failure_detail" IS NULL AND "failure_permanent" IS NULL));
